fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }
    
    let mut max_streak = 1;  // At least 1 for non-empty arrays
    let mut current_streak = 1;
    
    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            current_streak += 1;
            if current_streak > max_streak {
                max_streak = current_streak;
            }
        } else {
            current_streak = 1;  // Reset streak when not strictly increasing
        }
    }
    
    max_streak
}